import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.il0noOp3.js";const m=JSON.parse('{"title":"WAF — enumerated source for the Go-Live Well-Architected Review","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/waf-go-live-checklist.md","filePath":"frameworks/waf-go-live-checklist.md"}'),o={name:"frameworks/waf-go-live-checklist.md"};function s(i,t,n,c,l,h){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="waf-—-enumerated-source-for-the-go-live-well-architected-review" tabindex="-1">WAF — enumerated source for the Go-Live Well-Architected Review <a class="header-anchor" href="#waf-—-enumerated-source-for-the-go-live-well-architected-review" aria-label="Permalink to &quot;WAF — enumerated source for the Go-Live Well-Architected Review&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>waf.golive.yaml</code> is a production-readiness review of an Azure estate. It stands in for the <a href="https://learn.microsoft.com/en-us/assessments/b0f9a229-5f82-4f19-ae61-b7be31131f4e/" target="_blank" rel="noreferrer">Go-Live Well-Architected Review</a> assessment, for which Scout found no more than a landing page. Every rule cites an item number from the tables below.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/b0f9a229-5f82-4f19-ae61-b7be31131f4e/" target="_blank" rel="noreferrer">Go-Live | Well-Architected Review</a> (30-60 minutes, multiple choice and multiple response; question text not published)</td></tr><tr><td>Framework version</td><td>Azure Well-Architected Framework design review checklists on Microsoft Learn (unversioned; the extraction date is the version)</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>The assessment landing page and the five pillar design review checklists below were fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-25. Searches of Microsoft Learn for the assessment&#39;s title and for Azure go-live guidance returned nothing about it. Every property an automated item reads was checked against the collect.json contract in <code>src/collect/Invoke-Collect.ps1</code>; ARM semantics come from those existing projections and were not re-checked against a live estate.</td></tr></tbody></table><h2 id="what-exists-and-what-this-enumeration-is-not" tabindex="-1">What exists, and what this enumeration is NOT <a class="header-anchor" href="#what-exists-and-what-this-enumeration-is-not" aria-label="Permalink to &quot;What exists, and what this enumeration is NOT&quot;">​</a></h2><p><strong>Scout found nothing published about this assessment beyond its landing page.</strong> The page says the assessment helps you &quot;holistically evaluate an Azure workload in a go-forward motion across the five tenets of the Well-Architected Framework&quot;. It names no design areas, no questions and no guidance article, and Microsoft Learn searches returned no page that describes it. The only &quot;go-live&quot; guidance Learn returns belongs to other products (Dynamics 365, Power Pages, SAP on Azure) and was not used.</p><p>So this enumeration is <strong>Scout&#39;s own production-readiness review, built from the five pillar design review checklists</strong>, with attention on the gates a team should clear before launch: service level objectives defined, disaster recovery tested, monitoring and alerting in place, a security baseline enforced, cost guardrails set, and a safe deployment path. Its items do <strong>not</strong> map to Microsoft&#39;s questions, a Scout score is <strong>not</strong> comparable to a Go-Live Assessment result, and the <code>WAF-GOLIVE-*</code> IDs are Scout&#39;s. Each item cites the checklist code it draws on.</p><p>Sources:</p><ul><li>[RE] <a href="https://learn.microsoft.com/azure/well-architected/reliability/checklist" target="_blank" rel="noreferrer">Design review checklist for Reliability</a> (RE:01 to RE:10)</li><li>[SE] <a href="https://learn.microsoft.com/azure/well-architected/security/checklist" target="_blank" rel="noreferrer">Design review checklist for Security</a> (SE:01 to SE:12)</li><li>[CO] <a href="https://learn.microsoft.com/azure/well-architected/cost-optimization/checklist" target="_blank" rel="noreferrer">Design review checklist for Cost Optimization</a> (CO:01 to CO:14)</li><li>[OE] <a href="https://learn.microsoft.com/azure/well-architected/operational-excellence/checklist" target="_blank" rel="noreferrer">Design review checklist for Operational Excellence</a> (OE:01 to OE:11)</li><li>[PE] <a href="https://learn.microsoft.com/azure/well-architected/performance-efficiency/checklist" target="_blank" rel="noreferrer">Design review checklist for Performance Efficiency</a> (PE:01 to PE:12)</li></ul><h2 id="scope-an-estate-not-a-workload" tabindex="-1">Scope: an estate, not a workload <a class="header-anchor" href="#scope-an-estate-not-a-workload" aria-label="Permalink to &quot;Scope: an estate, not a workload&quot;">​</a></h2><p>Scout scans subscriptions, not one workload. An automated item reports on <strong>every</strong> resource of that type in the scanned scope. Anything that needs a fact Scout cannot read (SLOs, runbooks, rehearsals, threat models) is Manual: a person signs it off.</p><p>Automated items are <strong>gated</strong>: they run only when the relevant resources (or Advisor data, or governance data) exist, so an estate with none reports them Not assessed rather than passed. Items marked &quot;name heuristic&quot; match a policy assignment&#39;s display name and miss a differently named one.</p><p>Two readings rest on values Scout has not seen in a live estate: the Advisor reliability and operational-excellence category names (matched as <code>HighAvailability</code> or <code>Reliability</code>, and <code>OperationalExcellence</code>), and the <code>System</code> tier that WAF-GOLIVE-RE-06 uses to exclude SQL system databases.</p><h2 id="the-enumeration-—-57-items-across-the-five-pillars" tabindex="-1">The enumeration — 57 items across the five pillars <a class="header-anchor" href="#the-enumeration-—-57-items-across-the-five-pillars" aria-label="Permalink to &quot;The enumeration — 57 items across the five pillars&quot;">​</a></h2><h3 id="reliability-gates-waf-golive-re-—-14-items" tabindex="-1">Reliability gates (WAF-GOLIVE-RE) — 14 items <a class="header-anchor" href="#reliability-gates-waf-golive-re-—-14-items" aria-label="Permalink to &quot;Reliability gates (WAF-GOLIVE-RE) — 14 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-GOLIVE-RE-01</td><td>Critical user and system flows are identified and rated by business criticality</td><td>❌ Manual</td><td>RE:02</td></tr><tr><td>WAF-GOLIVE-RE-02</td><td>Reliability and recovery targets (SLO, RTO, RPO) are defined and agreed</td><td>❌ Manual</td><td>RE:04</td></tr><tr><td>WAF-GOLIVE-RE-03</td><td>Failure mode analysis is complete, with mitigations for each dependency</td><td>❌ Manual</td><td>RE:03</td></tr><tr><td>WAF-GOLIVE-RE-04</td><td>Virtual machines are deployed in availability zones</td><td>✅ <code>zoneRedundant</code> where the region has zones</td><td>RE:05</td></tr><tr><td>WAF-GOLIVE-RE-05</td><td>AKS node pools are spread across availability zones</td><td>✅ <code>allPoolsZoned</code></td><td>RE:05</td></tr><tr><td>WAF-GOLIVE-RE-06</td><td>SQL databases are zone-redundant</td><td>✅ <code>zoneRedundant</code>, system databases excluded</td><td>RE:05</td></tr><tr><td>WAF-GOLIVE-RE-07</td><td>Storage accounts use zone-redundant or geo-redundant replication</td><td>✅ storage <code>sku</code></td><td>RE:05</td></tr><tr><td>WAF-GOLIVE-RE-08</td><td>No autoscale setting is switched off</td><td>✅ autoscale <code>enabled</code></td><td>RE:06</td></tr><tr><td>WAF-GOLIVE-RE-09</td><td>Virtual machines are protected by Azure Backup</td><td>✅ virtual machine → backup protected item</td><td>RE:09</td></tr><tr><td>WAF-GOLIVE-RE-10</td><td>No protected item reports a failed last backup</td><td>✅ <code>lastBackupStatus</code></td><td>RE:09</td></tr><tr><td>WAF-GOLIVE-RE-11</td><td>Resiliency has been tested with load and fault-injection tests that meet the targets</td><td>❌ Manual — chaos experiments attached</td><td>RE:08</td></tr><tr><td>WAF-GOLIVE-RE-12</td><td>A disaster recovery plan is documented and has been tested end to end</td><td>❌ Manual</td><td>RE:09</td></tr><tr><td>WAF-GOLIVE-RE-13</td><td>Enabled metric alert rules are wired to an action group</td><td>✅ <code>actionGroupCount</code></td><td>RE:10</td></tr><tr><td>WAF-GOLIVE-RE-14</td><td>High-impact Advisor reliability recommendations are addressed</td><td>✅ Advisor reliability, high impact</td><td>RE:05, RE:09</td></tr></tbody></table><h3 id="security-gates-waf-golive-se-—-15-items" tabindex="-1">Security gates (WAF-GOLIVE-SE) — 15 items <a class="header-anchor" href="#security-gates-waf-golive-se-—-15-items" aria-label="Permalink to &quot;Security gates (WAF-GOLIVE-SE) — 15 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-GOLIVE-SE-01</td><td>A security baseline is established and the workload is measured against it</td><td>✅ a Defender for Cloud secure score per subscription (read by the Defender sweep); whether the baseline matches your standards is a design decision</td><td>SE:01</td></tr><tr><td>WAF-GOLIVE-SE-02</td><td>Microsoft Defender for Servers is enabled</td><td>✅ Defender plan tier (per subscription)</td><td>SE:01, SE:10</td></tr><tr><td>WAF-GOLIVE-SE-03</td><td>Microsoft Defender for SQL is enabled</td><td>✅ Defender for SQL tier (per subscription)</td><td>SE:10</td></tr><tr><td>WAF-GOLIVE-SE-04</td><td>Azure Policy assignments enforce the security baseline</td><td>✅ policy assignment exists (estate-wide)</td><td>SE:01</td></tr><tr><td>WAF-GOLIVE-SE-05</td><td>Access is least-privilege, conditional and auditable for users, operators and workload identities</td><td>❌ Manual — enabled Conditional Access policies that require MFA attached</td><td>SE:05</td></tr><tr><td>WAF-GOLIVE-SE-06</td><td>No network security group rule opens RDP or SSH to the internet</td><td>✅ internet-open inbound rule on port 22, 3389 or <code>*</code></td><td>SE:06</td></tr><tr><td>WAF-GOLIVE-SE-07</td><td>Storage accounts deny public network access by default</td><td>✅ <code>networkDefaultDeny</code></td><td>SE:04, SE:06</td></tr><tr><td>WAF-GOLIVE-SE-08</td><td>SQL servers do not allow public network access</td><td>✅ <code>publicNetworkAccess</code></td><td>SE:04, SE:06</td></tr><tr><td>WAF-GOLIVE-SE-09</td><td>Storage accounts require secure transfer</td><td>✅ <code>httpsOnly</code></td><td>SE:07</td></tr><tr><td>WAF-GOLIVE-SE-10</td><td>Storage accounts require TLS 1.2 or later</td><td>✅ <code>minTls</code></td><td>SE:07</td></tr><tr><td>WAF-GOLIVE-SE-11</td><td>Key vaults have soft delete and purge protection</td><td>✅ <code>softDelete</code>, <code>purgeProtection</code></td><td>SE:09</td></tr><tr><td>WAF-GOLIVE-SE-12</td><td>Web application firewall policies run in Prevention mode</td><td>✅ policy <code>mode</code></td><td>SE:06, SE:08</td></tr><tr><td>WAF-GOLIVE-SE-13</td><td>Threat monitoring is live and incident response procedures have been tested</td><td>❌ Manual</td><td>SE:10, SE:12</td></tr><tr><td>WAF-GOLIVE-SE-14</td><td>Secure development practice and a security testing regimen cover the release</td><td>❌ Manual</td><td>SE:02, SE:11</td></tr><tr><td>WAF-GOLIVE-SE-15</td><td>High-impact Advisor security recommendations are addressed</td><td>✅ Advisor security, high impact</td><td>SE:01, SE:08</td></tr></tbody></table><h3 id="cost-guardrail-gates-waf-golive-co-—-9-items" tabindex="-1">Cost guardrail gates (WAF-GOLIVE-CO) — 9 items <a class="header-anchor" href="#cost-guardrail-gates-waf-golive-co-—-9-items" aria-label="Permalink to &quot;Cost guardrail gates (WAF-GOLIVE-CO) — 9 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-GOLIVE-CO-01</td><td>A cost model exists with a budget that includes a buffer for unplanned spend</td><td>❌ Manual</td><td>CO:02</td></tr><tr><td>WAF-GOLIVE-CO-02</td><td>Cost Management budgets with alerts exist</td><td>✅ budget exists (estate-wide)</td><td>CO:03</td></tr><tr><td>WAF-GOLIVE-CO-03</td><td>Cost data is reviewed against the budget, with anomaly detection and alerts</td><td>❌ Manual</td><td>CO:03</td></tr><tr><td>WAF-GOLIVE-CO-04</td><td>A policy limits what can be deployed (allowed locations, sizes or resource types)</td><td>✅ guardrail policy assignment (name heuristic)</td><td>CO:04</td></tr><tr><td>WAF-GOLIVE-CO-05</td><td>No unattached managed disks remain</td><td>✅ unattached disks</td><td>CO:07</td></tr><tr><td>WAF-GOLIVE-CO-06</td><td>No public IP addresses are left unassociated</td><td>✅ unassociated public IPs</td><td>CO:07</td></tr><tr><td>WAF-GOLIVE-CO-07</td><td>High-impact Advisor cost recommendations are addressed</td><td>✅ Advisor cost, high impact</td><td>CO:07, CO:12</td></tr><tr><td>WAF-GOLIVE-CO-08</td><td>Rates, reservations and licence benefits have been evaluated for steady-state usage</td><td>❌ Manual — reservations attached</td><td>CO:05</td></tr><tr><td>WAF-GOLIVE-CO-09</td><td>Non-production and disaster recovery environments are sized and scheduled to their purpose</td><td>❌ Manual</td><td>CO:08</td></tr></tbody></table><h3 id="safe-deployment-and-operations-gates-waf-golive-oe-—-10-items" tabindex="-1">Safe deployment and operations gates (WAF-GOLIVE-OE) — 10 items <a class="header-anchor" href="#safe-deployment-and-operations-gates-waf-golive-oe-—-10-items" aria-label="Permalink to &quot;Safe deployment and operations gates (WAF-GOLIVE-OE) — 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-GOLIVE-OE-01</td><td>Standard operating practices and runbooks exist for routine, ad-hoc and emergency operations</td><td>❌ Manual</td><td>OE:01, OE:02</td></tr><tr><td>WAF-GOLIVE-OE-02</td><td>Infrastructure is deployed from code through a standard IaC approach</td><td>❌ Manual</td><td>OE:05</td></tr><tr><td>WAF-GOLIVE-OE-03</td><td>Changes flow through automated pipelines with quality gates and testing across environments</td><td>❌ Manual</td><td>OE:06, OE:09</td></tr><tr><td>WAF-GOLIVE-OE-04</td><td>A safe deployment plan exists, with progressive exposure and a tested rollback</td><td>❌ Manual — deployment slots attached</td><td>OE:11</td></tr><tr><td>WAF-GOLIVE-OE-05</td><td>A Log Analytics workspace exists to receive operational telemetry</td><td>✅ workspace exists</td><td>OE:07</td></tr><tr><td>WAF-GOLIVE-OE-06</td><td>Diagnostic settings cover at least 80% of each resource type</td><td>✅ <code>coveragePct</code> per type, gated on a measured sweep</td><td>OE:07</td></tr><tr><td>WAF-GOLIVE-OE-07</td><td>An enabled action group exists to route alerts</td><td>✅ enabled action group exists</td><td>OE:07, OE:08</td></tr><tr><td>WAF-GOLIVE-OE-08</td><td>An incident management process with defined roles is documented and has been rehearsed</td><td>❌ Manual</td><td>OE:08</td></tr><tr><td>WAF-GOLIVE-OE-09</td><td>Virtual machines use platform-orchestrated patching</td><td>✅ <code>patchMode</code></td><td>OE:10</td></tr><tr><td>WAF-GOLIVE-OE-10</td><td>High-impact Advisor operational excellence recommendations are addressed</td><td>✅ Advisor operational excellence, high impact</td><td>OE:07, OE:10</td></tr></tbody></table><h3 id="performance-gates-waf-golive-pe-—-9-items" tabindex="-1">Performance gates (WAF-GOLIVE-PE) — 9 items <a class="header-anchor" href="#performance-gates-waf-golive-pe-—-9-items" aria-label="Permalink to &quot;Performance gates (WAF-GOLIVE-PE) — 9 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-GOLIVE-PE-01</td><td>Numeric performance targets are defined for every workload flow</td><td>❌ Manual</td><td>PE:01</td></tr><tr><td>WAF-GOLIVE-PE-02</td><td>Capacity planning is done for launch load and expected growth, including quotas</td><td>❌ Manual</td><td>PE:02</td></tr><tr><td>WAF-GOLIVE-PE-03</td><td>No Free or Shared App Service plan is used</td><td>✅ App Service plan <code>sku</code></td><td>PE:03</td></tr><tr><td>WAF-GOLIVE-PE-04</td><td>No Azure AI Search service is on the Free tier</td><td>✅ search service <code>sku</code></td><td>PE:03</td></tr><tr><td>WAF-GOLIVE-PE-05</td><td>Application performance telemetry exists for web applications</td><td>✅ Application Insights exists where web apps exist</td><td>PE:04</td></tr><tr><td>WAF-GOLIVE-PE-06</td><td>Standard, Premium and Isolated App Service plans are scaled by an enabled autoscale setting</td><td>✅ App Service plan → enabled autoscale setting</td><td>PE:05</td></tr><tr><td>WAF-GOLIVE-PE-07</td><td>Performance has been tested in a production-like environment against the targets</td><td>❌ Manual — Load Testing resources attached</td><td>PE:06</td></tr><tr><td>WAF-GOLIVE-PE-08</td><td>Critical flows are prioritized, and a response plan exists for live performance issues</td><td>❌ Manual</td><td>PE:09, PE:11</td></tr><tr><td>WAF-GOLIVE-PE-09</td><td>High-impact Advisor performance recommendations are addressed</td><td>✅ Advisor performance, high impact</td><td>PE:03, PE:12</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pillar gates</th><th>Items</th><th>Automated (✅)</th><th>Manual (❌)</th></tr></thead><tbody><tr><td>Reliability gates</td><td>14</td><td>9</td><td>5</td></tr><tr><td>Security gates</td><td>15</td><td>12</td><td>3</td></tr><tr><td>Cost guardrail gates</td><td>9</td><td>5</td><td>4</td></tr><tr><td>Safe deployment and operations gates</td><td>10</td><td>5</td><td>5</td></tr><tr><td>Performance gates</td><td>9</td><td>5</td><td>4</td></tr><tr><td><strong>Total</strong></td><td><strong>57</strong></td><td><strong>36</strong></td><td><strong>21</strong></td></tr></tbody></table><p>Where an item says &quot;attached&quot;, Scout carries the matching resources as evidence on the Manual finding but does not score them.</p>',28)])])}const p=e(o,[["render",s]]);export{m as __pageData,p as default};
